import{_ as a,o as t,c as s,O as i}from"./chunks/framework.4XV3vnnU.js";const u=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/deployment.md","filePath":"documentation/deployment.md","lastUpdated":1793117788000}'),n={name:"documentation/deployment.md"};function r(o,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><p>Naira is installed with one Helm chart. The chart deploys the catalog with its plugin sidecars, the UI and the portal, plus a PostgreSQL database. It does not deploy the systems the plugins read from, nor Keycloak. Those already exist in your environment, or, for evaluation, come from the <a href="https://github.com/naira-project/test-dependencies" target="_blank" rel="noreferrer">test-dependencies</a> chart.</p><p>The <a href="https://github.com/naira-project/naira/tree/main/deploy/charts/naira" target="_blank" rel="noreferrer">chart README</a> is the reference for every value, constraint and validation. This page covers what you need to plan an installation.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Kubernetes cluster and Helm.</li><li>A Keycloak realm with an OIDC client for the portal. The catalog accepts tokens from this realm only.</li><li>The systems you want to catalog, reachable from the cluster: a LiteLLM gateway, MLflow, OpenMetadata, MCP servers, FluxCD in the cluster, and so on. Disable the plugins for systems you do not have.</li><li>Secrets with the credentials the enabled plugins need, the portal&#39;s OIDC client secret and the database passwords. The chart can create development Secrets from values, but for anything beyond a laptop, supply them yourself.</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Released charts are published as OCI artifacts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> naira</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oci://ghcr.io/naira-project/charts/naira</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">releas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> idp-system</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-namespace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span></code></pre></div><p>Container images for the catalog, the UI, the portal and each plugin are published to <code>ghcr.io/naira-project</code> with every release, for amd64 and arm64, with a software bill of materials attached. Releases are listed on <a href="https://github.com/naira-project/naira/releases" target="_blank" rel="noreferrer">GitHub</a>.</p><p>From a checkout, build the chart dependencies first, since the PostgreSQL subchart is not vendored:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependency</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/charts/naira</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> naira</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/charts/naira</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> idp-system</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-namespace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span></code></pre></div><p>The chart refuses to render with bare defaults: it needs a source for the catalog Secret and the portal Secret, and it validates the plugin, database and Secret configuration before anything is applied.</p><h2 id="what-to-configure" tabindex="-1">What to configure <a class="header-anchor" href="#what-to-configure" aria-label="Permalink to &quot;What to configure&quot;">​</a></h2><p><strong>Addresses the browser uses.</strong> <code>keycloak.issuer</code>, <code>keycloak.authUrl</code>, <code>keycloak.baseDomain</code> and <code>portal.uiBaseUrl</code> default to localhost for the port-forwarded development setup. Anywhere else, set them to the addresses users reach in the browser.</p><p><strong>Plugins.</strong> Each plugin is one entry under <code>catalog.plugins.&lt;name&gt;</code> with <code>enabled</code>, <code>schedule</code>, <code>env</code>, Secret references, and for cluster-reading plugins <code>rbac.rules</code>. Point the <code>*_BASE_URL</code> variables at your systems. Plugins that read Secrets cluster-wide or need a token are off by default. See <a href="/pr-preview/pr-12/documentation/plugins">Plugins</a>.</p><p><strong>Tech Radar.</strong> Enable the <code>tech-radar</code> plugin and provide the radar file through <code>config.data</code> or an existing ConfigMap. See <a href="/pr-preview/pr-12/documentation/tech-radar">Tech Radar</a>.</p><p><strong>Database.</strong> The chart runs a PostgreSQL server by default and seeds one database per entry in <code>database.databases</code>, with its own role and password, idempotently. Set <code>postgresql.enabled=false</code> and <code>database.host</code> to use an existing server, and a strict <code>database.sslmode</code> in that case. The catalog does not persist its graph there yet.</p><p><strong>Metrics.</strong> <code>ui.prometheus.upstream</code> names the Prometheus-compatible endpoint the UI queries for the metric panels on inference endpoint pages. The UI forwards the user&#39;s token, so the endpoint is never exposed unauthenticated.</p><p><strong>Scheduling and security.</strong> <code>nodeSelector</code>, <code>tolerations</code>, <code>affinity</code>, <code>priorityClassName</code>, probes and security contexts are available per component. The catalog and the plugins run as non-root with all capabilities dropped and meet the restricted Pod Security standard. A NetworkPolicy restricts ingress to the catalog to the UI pods.</p><h2 id="constraints-to-know" tabindex="-1">Constraints to know <a class="header-anchor" href="#constraints-to-know" aria-label="Permalink to &quot;Constraints to know&quot;">​</a></h2><ul><li>One release per namespace. Namespaced objects have fixed names. Several releases per cluster work as long as release names differ.</li><li>The catalog connects to every enabled plugin at startup and exits if one is unreachable. Check the plugin sidecar logs when the catalog does not become ready.</li><li>The catalog store is in memory. A restart empties it until the plugins run again, so give plugins a schedule rather than relying on manual runs.</li><li>Plugin sidecars listen on loopback and have no probes.</li></ul><h2 id="development-environment" tabindex="-1">Development environment <a class="header-anchor" href="#development-environment" aria-label="Permalink to &quot;Development environment&quot;">​</a></h2><p>For a local cluster, <a href="/pr-preview/pr-12/documentation/getting-started">Getting Started</a> describes the kind and Tilt setup. It uses <code>values-dev.yaml</code>, which is the only values file that creates Secrets from values, together with the test-dependencies chart for Keycloak, LiteLLM, MLflow, llama.cpp and a mock MCP server. The dependencies chart also offers OpenMetadata, vLLM and a monitoring stack with Prometheus and Grafana behind tags.</p><h2 id="releases-and-versioning" tabindex="-1">Releases and versioning <a class="header-anchor" href="#releases-and-versioning" aria-label="Permalink to &quot;Releases and versioning&quot;">​</a></h2><p>Naira uses conventional commits and <a href="https://github.com/googleapis/release-please" target="_blank" rel="noreferrer">release-please</a>. A release PR collects the changes since the last release, and merging it tags the release, publishes the images and the chart, and updates the <a href="https://github.com/naira-project/naira/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>. During the alpha phase, releases can contain breaking changes.</p>`,25)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
